function newCaptcha(){const alphabet='ABCDEFGHJKLMNPQRSTUVWXYZ23456789';const code=Array.from({length:6},()=>alphabet[Math.floor(Math.random()*alphabet.length)]).join('');$('captchaCode').textContent=code;$('captchaInput').value='';return code;}
function populateLogin(){
  $('loginDomain').innerHTML=domainProfiles.map(profile=>`<option value="${profile.id}">${escapeHtml(profile.name)}</option>`).join('');
  const refreshAccounts=()=>{const domain=$('loginDomain').value;const accounts=loginAccounts.filter(account=>account.domain===domain);$('loginAccount').innerHTML='<option value="">Select an account</option>'+accounts.map(account=>`<option value="${account.id}">${account.id} · ${account.role}</option>`).join('');};
  $('loginDomain').addEventListener('change',refreshAccounts);refreshAccounts();
  $('loginAccountDirectory').innerHTML=domainProfiles.map(profile=>`<section><b>${escapeHtml(profile.name)}</b><span>${loginAccounts.filter(account=>account.domain===profile.id).map(account=>`<code>${account.id}</code>`).join(' · ')}</span></section>`).join('');
  newCaptcha();
}
