function notify(message){toast.textContent=message;toast.classList.add('show');clearTimeout(toastTimer);toastTimer=setTimeout(()=>toast.classList.remove('show'),2700)}
let sentinelPollInitialized=false;const seenSentinelAlertIds=new Set();
function renderLiveSentinelAlerts(){
  const scoped=activeDomain==='all'?liveSentinelAlerts:liveSentinelAlerts.filter(alert=>portalDomainMap[alert.organization_domain]===activeDomain);const panel=$('sentinelAlertPanel');if(!panel)return;
  panel.hidden=!scoped.length;$('sentinelAlertCount').textContent=scoped.length?`${scoped.length} alert${scoped.length===1?'':'s'} from the local SENTINEL AI receiver`:'No live notifications received';
  $('sentinelAlertRows').innerHTML=scoped.slice(0,6).map(alert=>{
    const agents=alert.agents||{},investigation=agents.investigation||{},risk=agents.risk_assessment||{},document=agents.document_verification||{},response=agents.response||{};
    const timeline=Array.isArray(investigation.timeline)?investigation.timeline:[];
    const eventLabel=alert.event_type==='unusual_login'?'Unusual login':alert.event_type.replaceAll('_',' ');
    const timelineMarkup=timeline.map(item=>`<li><b>${escapeHtml(new Date(item.timestamp).toLocaleTimeString())}</b> ${escapeHtml(item.event_type.replaceAll('_',' '))} · ${escapeHtml(item.username)} · ${escapeHtml(item.source_ip)}</li>`).join('');
    const recommendations=Array.isArray(response.recommended_actions)?response.recommended_actions.join(' · '):response.finding||'Human review required.';
    const actionButton=response.password_change_available?(response.status==='approved'?'<button class="sentinel-action" disabled>Password change required</button>':`<button class="sentinel-action" data-password-change="${escapeHtml(alert.alert_id)}">Require immediate password change</button>`):'';
    const involvedList=(investigation.involved_users||[]).length?investigation.involved_users:(investigation.attempted_user_ids||[]);const involved=involvedList.join(', ')||investigation.attempted_user_id||'Unknown';
    return `<article class="sentinel-alert-row"><div class="sentinel-alert-title"><span class="sentinel-risk ${String(alert.risk_level).toLowerCase()}">${escapeHtml(alert.risk_level)} risk · ${alert.risk_score}/100</span><b>${escapeHtml(alert.organization_name)} · ${escapeHtml(eventLabel)}</b></div><p>User ${escapeHtml(alert.username)} · Source IP ${escapeHtml(alert.source_ip)} · ${escapeHtml(new Date(alert.timestamp).toLocaleString())}</p><small>${escapeHtml(alert.summary)} · Status: ${escapeHtml(alert.incident_status)}</small><details class="sentinel-agent-details"><summary>Investigation, risk and response details</summary><p><b>Investigation:</b> ${escapeHtml(investigation.finding||'Related sign-in records reviewed.')}</p><p><b>Involved user(s):</b> ${escapeHtml(involved)}</p>${timelineMarkup?`<ol>${timelineMarkup}</ol>`:''}<p><b>Risk assessment:</b> ${escapeHtml(risk.explanation||alert.summary)}</p><p><b>Document verification:</b> ${escapeHtml(document.finding||'No file linked to this alert.')}${document.current_sha256?` · ${escapeHtml(document.status)} · Current SHA-256: ${escapeHtml(document.current_sha256)} · Reference SHA-256: ${escapeHtml(document.reference_sha256||'Unavailable')}`:''}</p><p><b>Response recommendation:</b> ${escapeHtml(recommendations)}</p></details>${actionButton}</article>`;
  }).join('');
  const badge=$('sentinelAlertBadge');badge.hidden=!liveSentinelAlerts.length;badge.textContent=String(liveSentinelAlerts.length);$('notifyBtn').classList.toggle('has-live-alerts',Boolean(liveSentinelAlerts.length));
}async function pollSentinelAlerts(){
  try{const response=await fetch('http://127.0.0.1:8000/api/sentinel/alerts');if(!response.ok)return;const latest=await response.json();const fresh=latest.filter(alert=>!seenSentinelAlertIds.has(alert.alert_id));latest.forEach(alert=>seenSentinelAlertIds.add(alert.alert_id));liveSentinelAlerts=latest;renderLiveSentinelAlerts();if(sentinelPollInitialized&&fresh.length)notify(`SENTINEL AI detected ${fresh.length} suspicious event${fresh.length===1?'':'s'} in ${fresh[0].organization_name}. Review the notification panel.`);sentinelPollInitialized=true;}catch{}
}
