function parseCsv(text){
  const rows=[];let row=[],cell='',quoted=false;
  for(let i=0;i<text.length;i++){const ch=text[i];if(ch==='"'&&quoted&&text[i+1]==='"'){cell+='"';i++}else if(ch==='"'){quoted=!quoted}else if(ch===','&&!quoted){row.push(cell);cell=''}else if((ch==='\n'||ch==='\r')&&!quoted){if(ch==='\r'&&text[i+1]==='\n')i++;row.push(cell);if(row.some(value=>value.trim()))rows.push(row);row=[];cell=''}else cell+=ch;}
  if(cell.length||row.length){row.push(cell);rows.push(row)}
  if(rows.length<2)return[];
  const headers=rows.shift().map(value=>value.trim().toLowerCase().replace(/^\uFEFF/,''));
  return rows.map(values=>Object.fromEntries(headers.map((header,index)=>[header,(values[index]||'').trim()])));
}
function resolveDomain(value,context=''){
  const label=String(value||'').toLowerCase();const direct=domainProfiles.find(profile=>profile.id===label||profile.name.toLowerCase()===label||profile.short.toLowerCase()===label);if(direct)return direct.id;
  const text=`${label} ${context}`.toLowerCase();
  const rules=[['banking',/bank|finance|payroll|payment|treasury/],['healthcare',/health|hospital|patient|clinical|medical/],['education',/college|university|student|campus|research/],['retail',/retail|e-commerce|ecommerce|storefront|checkout|order|refund|pos/],['manufacturing',/manufacturing|plant|factory|production|malware|ot endpoint/],['government',/government|citizen|public sector|restricted record/],['public-services',/public services|public-service|administrator|admin|server|network|infrastructure|firewall/],['corporate',/corporate|business|cafe|shop|owner|employee/]];
  for(const [id,pattern]of rules)if(pattern.test(text))return id;
  return activeDomain==='all'?'corporate':activeDomain;
}
