    $('logSourceLabel').textContent=file.name;$('logUploadStatus').innerHTML=`<span>✓</span> Read ${logs.length} events from ${escapeHtml(file.name)} in this browser.`;$('logSearch').value='';renderAll();notify(`${logs.length} CSV events loaded. Run detection to investigate.`);
