function updateHashButton(){ $('compareHashes').disabled=!($('currentDocFile').files[0]&&$('referenceDocFile').files[0]); }
async function sha256(file){const digest=await crypto.subtle.digest('SHA-256',await file.arrayBuffer());return [...new Uint8Array(digest)].map(byte=>byte.toString(16).padStart(2,'0')).join('');}
async function compareDocuments(){
  const current=$('currentDocFile').files[0],reference=$('referenceDocFile').files[0];if(!current||!reference)return;
  const output=$('hashResult');output.className='hash-result visible';output.textContent='Calculating SHA-256 hashes locally…';$('compareHashes').disabled=true;
  try{
    const [currentHash,referenceHash]=await Promise.all([sha256(current),sha256(reference)]);const match=currentHash===referenceHash;
    output.className=`hash-result visible ${match?'match':'mismatch'}`;
    output.innerHTML=`<b>${match?'✓ Hashes match':'⚠ Hash mismatch · the files differ'}</b><div class="hash-digest"><span>Current · ${escapeHtml(current.name)}</span><code>${currentHash}</code><span>Reference · ${escapeHtml(reference.name)}</span><code>${referenceHash}</code></div>`;
    audit.unshift({icon:match?'✓':'▤',title:`SHA-256 comparison ${match?'matched':'found a mismatch'}`,detail:`${current.name} compared with reference ${reference.name} · Calculated locally in this browser`,time:'Just now',domain:activeDomain==='all'?'':activeDomain});renderAudit();notify(match?'SHA-256 hashes match.':'SHA-256 mismatch found. Review the file versions.');
  }catch(error){output.className='hash-result visible error';output.textContent='Could not calculate hashes. Use a modern browser on localhost or HTTPS.';}
  updateHashButton();
}

// Living Off the Land demo: the existing dashboard remains intact, while this
// view uses the local FastAPI + SQLite service for persistent synthetic runs.
async function lotlRequest(path,options={}){
  const response=await fetch(`${lotlApi}${path}`,{...options,headers:{'Content-Type':'application/json',...(options.headers||{})}});
  const payload=await response.json().catch(()=>({}));
  if(!response.ok)throw new Error(payload.detail||`Local LotL service returned ${response.status}.`);
  return payload;
}
function mergeLotlIncidents(items){
  for(let index=incidents.length-1;index>=0;index--)if(lotlIncidentIds.has(incidents[index].id))incidents.splice(index,1);
  lotlIncidentIds=new Set();
  for(const incident of items){
    const score=incident.risk_assessment?.score||0;const status=incident.status||'Awaiting human approval';
    const statusKey=status.startsWith('Awaiting')?'approval':status.startsWith('Approved')?'contained':status.startsWith('Rejected')?'resolved':'investigating';
    const profile=domainProfiles.find(item=>item.id===incident.organization_domain);
    const first=incident.events?.[0]||{};
    const row={id:incident.incident_id,title:`Living Off the Land · ${incident.name}`,type:'LotL behavior anomaly',entity:incident.username,domain:incident.organization_domain||'corporate',score,severity:incident.risk_assessment?.level||'Low',time:new Date(incident.created_at).toLocaleString(),status,statusKey,source:'LotL behavior engine',location:`${first.source_ip||'Unknown IP'} · ${first.device||'Unknown device'}`,device:first.device||'Unknown device',events:incident.events?.length||1,failed:0,successful:true,sensitivity:first.resource||'Administrative activity',hash:'No linked document · SHA-256 page available',recommendation:incident.response?.action||'Review activity',agentSummary:incident.risk_assessment?.explanation||'Behavioral anomaly requires review.',lotlIncident:incident};
    incidents.push(row);lotlIncidentIds.add(row.id);
  }
}
function renderLotlAgents(){
  const latest=lotlData?.runs?.[0];if(!latest?.workflow?.length)return;
  const latestByName=latest.workflow[latest.workflow.length-1];
  const sample=latest.workflow;
  agents[0].task=`Reviewed ${latest.event_count} events · ${latest.classifications.filter(value=>value==='suspicious').length} suspicious`;
  agents[0].output=sample.map(row=>row.detection?.detection?.factors?.map(factor=>factor.factor).join(', ')).filter(Boolean).slice(0,3).join(' · ')||'No material behavior deviation found in the selected run.';
  agents[1].task=`Correlated ${sample.length} event(s) · ${latest.incidents?.length||0} incident(s)`;
  agents[1].output=latest.incidents?.[0]?.investigation?.observed_facts?.join(' ')||'Timeline built from synthetic activity and historical context.';
  agents[2].task=`${latest.incidents?.length||0} risk score(s) · heuristic`;
  agents[2].output=latest.incidents?.[0]?.risk_assessment?.explanation||'Score uses observable baseline deviations; no validated attack probability is claimed.';
  const verifiedIncident=latest.incidents?.[0];
  const affectedDocuments=verifiedIncident?.verification?.affected_documents||[];
  agents[3].task=affectedDocuments.length?`${affectedDocuments.length} affected document(s) identified`:'Document path unavailable from activity logs';
  agents[3].output=affectedDocuments.length?affectedDocuments.map(document=>`${document.resource} · integrity ${document.integrity_status}`).join('; '):(verifiedIncident?.verification?.result||'No suspicious document activity was identified in the selected run.');
  agents[4].task=latest.incidents?.length?`${latest.incidents.length} recommendation(s) await human review`:'Monitoring only · no impactful response requested';
  agents[4].output=latest.incidents?.[0]?.response?.action||'No disruptive action was needed for the expected activity.';
  if(latestByName)agents[4].state=latest.incidents?.length?'Active':'Standby';
}
