  const latestRun=lotlData.runs?.[0];const workflow=latestRun?.workflow||[];const workflowItem=workflow.slice().sort((a,b)=>(b.risk_assessment?.score||0)-(a.risk_assessment?.score||0))[0];
  if(workflowItem){const verification=latestRun?.incidents?.[0]?.verification||workflowItem.verification;const stages=[['Detection Agent',workflowItem.detection?.detection?.suspicious?'Suspicious pattern flagged':'Expected / normal activity',workflowItem.detection?.detection?.factors?.map(row=>row.factor).join(', ')||'No behavior deviation found.'],['Investigation Agent',`${workflowItem.investigation?.related_event_count||0} related event(s)`,workflowItem.investigation?.observed_facts?.join(' ')||'Chronological activity correlated.'],['Risk Assessment Agent',`${workflowItem.risk_assessment?.score||0}/100 · ${workflowItem.risk_assessment?.level||'Low'} · ${workflowItem.risk_assessment?.confidence||'Medium'} confidence`,workflowItem.risk_assessment?.explanation||'Risk factors recorded.'],['Response Agent',workflowItem.response?.urgency||'Routine',workflowItem.response?.action||'Continue monitoring.'],['Verification Agent',verification?.status||'Awaiting review',verification?.result||'A human decision is required before verification.']];$('lotlAgentStages').innerHTML=stages.map(([name,status,detail])=>`<article class="lotl-agent-stage"><b>${escapeHtml(name)}</b><span>${escapeHtml(status)}</span><small>${escapeHtml(detail)}</small></article>`).join('');}else $('lotlAgentStages').innerHTML='<div class="lotl-empty">Agent findings appear after a scenario run or event import.</div>';
